// Build and run `opencode run --format json -m PROVIDER/MODEL --auto --standalone MESSAGE` (v2 CLI).
// No working-dir flag exists on `run`, so the process cwd is the slice dir. `--standalone` keeps a spawn off the
// shared background service. Tier routing comes from tiers.json (generated by tiers.mjs), never hard-coded.
import { spawnSync, execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
export const TIERS_PATH = join(HERE, '..', 'tiers.json');
export const loadTiers = (path = TIERS_PATH) => JSON.parse(readFileSync(path, 'utf8'));

export function listModels(bin = 'opencode') {
  const parse = () => execFileSync(bin, ['models'], { encoding: 'utf8', timeout: 60000 }).split('\n').map((l) => l.trim()).filter((l) => /^[^/\s]+\/\S+$/.test(l));
  const first = parse();
  return first.length ? first : parse(); // a cold background service can print nothing once
}

// provider: route this spawn to a provider; accepted only when the model list has a model under it.
export function buildSpawn({ role, tier, brief = '', reason = '', dir, provider } = {}, tiers = loadTiers(), models = null) {
  const map = tiers.tiers || tiers;
  if (!tier || !(tier in map)) return { outcome: 'UNTIERED_SPAWN', reason: tier ? `unknown tier ${tier}` : 'no tier named' };
  let effective = tier;
  const event = { type: 'spawn', role };
  if (tier === 'T1' && !String(reason).trim()) { effective = 'T2'; event.downgraded_from = 'T1'; }
  let model = map[effective];
  if (provider) {
    const list = models || listModels();
    model = list.find((m) => m.startsWith(`${provider}/`)) || null;
    if (!model) return { outcome: 'TIER_UNROUTED', reason: `${provider}/ not listed by opencode models` };
  }
  if (!model) return { outcome: 'UNTIERED_SPAWN', reason: `tier ${effective} unmapped` };
  event.tier = effective; event.model = model;
  const cwd = dir || process.cwd();
  const argv = ['opencode', 'run', '--format', 'json', '-m', model, '--auto', '--standalone', String(brief)];
  return { outcome: 'ok', tier: effective, model, argv, cwd, event };
}

export function runOpencode(argv, { cwd = process.cwd(), timeoutMs = 3600000 } = {}) {
  const r = spawnSync(argv[0], argv.slice(1), { cwd, env: process.env, encoding: 'utf8', timeout: timeoutMs, killSignal: 'SIGKILL', maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] });
  return { status: r.status, signal: r.signal, stdout: r.stdout || '', stderr: r.stderr || '', error: r.error ? (r.error.code === 'ETIMEDOUT' ? 'timeout' : r.error.message) : null };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const a = process.argv.slice(2);
  const get = (f) => (a.includes(f) ? a[a.indexOf(f) + 1] : undefined);
  const models = get('--models') ? readFileSync(get('--models'), 'utf8').split('\n').map((l) => l.trim()).filter(Boolean) : null;
  const r = buildSpawn({ role: get('--role'), tier: get('--tier'), reason: get('--reason') || '', brief: get('--brief') || '', dir: get('--dir'), provider: get('--provider') }, loadTiers(get('--tiers') || TIERS_PATH), models);
  console.log(JSON.stringify(r));
  process.exit(r.outcome === 'ok' ? 0 : 1);
}
